"""v0.3 helpers: parity with arbiter-sdk/test/vectors.v03.json (generated by the TS SDK, whose v0.3 hashes are
checked against the Solidity contract on anvil in arbiter-sdk/test/v03.test.ts) and non-collision with v0.2."""
import json
from dataclasses import replace
from pathlib import Path

from eth_account import Account
from eth_account.messages import encode_typed_data

from agentcoin_core import arbiter as v02
from agentcoin_core import arbiter_v03 as a

REPO = next(p for p in Path(__file__).resolve().parents if (p / "arbiter-sdk").is_dir())  # repo root
V = json.loads((REPO / "arbiter-sdk/test/vectors.v03.json").read_text())


def _terms(d: dict) -> a.TermsV03:
    return a.TermsV03(d["evaluator"], d["criteriaHash"], d["scheduleHash"], d["requiredTotal"], int(d["bpsTable"], 16),
                      d["submitBy"], d["evalWindow"], d["submitter"])


def test_constants():
    assert a.TERMS_V03_TYPEHASH == V["typehashes"]["terms"]
    assert a.TERMS_V03_TYPEHASH != v02.TERMS_TYPEHASH
    assert (a.OUTSIDE_VERDICT_TYPEHASH, a.BUYER_ACCEPTANCE_TYPEHASH) == (V["typehashes"]["verdict"], V["typehashes"]["acceptance"])
    assert a.EIP712_VERSION == "0.3" and v02.EIP712_VERSION == "0.2"


def test_terms_hash_binds_submitter():
    t = _terms(V["terms"])
    assert a.hash_terms_v03(t) == V["termsHash"]
    assert hex(a.terms_salt(a.hash_terms_v03(t), 42)) == V["termsSalt42"]
    t0 = replace(t, submitter=a.ZERO_ADDRESS)
    assert a.hash_terms_v03(t0) == V["termsHashZeroSubmitter"] != V["termsHash"]
    v2t = v02.Terms(t.evaluator, t.criteria_hash, t.schedule_hash, t.required_total, t.bps_table, t.submit_by, t.eval_window)
    assert v02.terms_hash(v2t) != a.hash_terms_v03(t0)
    assert a.effective_submitter(V["receiver"], t) == t.submitter
    assert a.effective_submitter(V["receiver"], t0) == V["receiver"]


def test_verdict_and_acceptance_digests_and_domain_separation():
    t = _terms(V["terms"])
    v = V["verdict"]
    assert a.build_verdict_v03(v["paymentInfoHash"], t, v["deliverableHash"], v["resultDigest"], v["passMask"], v["reasonHash"]) == v
    assert a.verdict_digest_v03(V["chainId"], V["arbiter"], v) == V["verdictDigest"]
    assert a.buyer_acceptance_digest_v03(V["chainId"], V["arbiter"], V["acceptance"]) == V["acceptanceDigest"]
    assert v02.verdict_digest(V["chainId"], V["arbiter"], v) == V["verdictDigestV02Domain"] != V["verdictDigest"]
    acct = Account.create()
    td = a.verdict_typed_data_v03(V["chainId"], V["arbiter"], v)
    sig = acct.sign_message(encode_typed_data(full_message=td)).signature
    assert Account.recover_message(encode_typed_data(full_message=td), signature=sig) == acct.address
    td2 = v02.verdict_typed_data(V["chainId"], V["arbiter"], v)
    assert Account.recover_message(encode_typed_data(full_message=td2), signature=sig) != acct.address


def test_submitter_is_payer_rejected():
    t = _terms(V["terms"])
    payer = "0x" + "ab" * 20
    other = "0x" + "cd" * 20
    assert a.validate_bind_v03(payer, V["receiver"], t) == []
    as_payer = replace(t, submitter=payer.upper().replace("0X", "0x"))
    assert a.submitter_is_payer(payer, V["receiver"], as_payer)
    assert any("SubmitterIsPayer" in e for e in a.validate_bind_v03(payer, V["receiver"], as_payer))
    zero = replace(t, submitter=a.ZERO_ADDRESS)
    assert a.submitter_is_payer(payer, payer, zero)
    assert any("SubmitterIsPayer" in e for e in a.validate_bind_v03(payer, payer, zero))
    assert not a.submitter_is_payer(payer, other, zero)
    assert any("EvaluatorConflict" in e for e in a.validate_bind_v03(payer, V["receiver"], replace(t, submitter=t.evaluator)))
